    pathlib.Path(conf_path).write_text(conf_content)
    env=os.environ.copy()
    env["PIER_CONFIG_PATH"]=conf_path
    res=subprocess.run([exe, "list"], capture_output=True, text=True, env=env)
    out=res.stdout
    # extract command column from line containing long
    for line in out.splitlines():
        if "long" in line and "Alias" not in line:
            # split by ⋮
            parts=line.split("⋮")
            if len(parts)>=4:
                cmd_displayed=parts[3].strip()
                return cmd_displayed, len(cmd_displayed), out
    return None, None, out

# try various configs
candidates = []

# keys to try
keys_display = ["cmd_display", "display", "cmd_display_mode", "command_display"]
keys_width = ["cmd_display_width", "cmd_width", "display_width", "width", "cmd_display_length"]

# values
for dkey in keys_display:
    for wkey in keys_width:
        for dval in ["full", "short"]:
            for wval in [10, 20]:
                for section in ["config", "default", ""]:
                    if section=="":
                        conf = base_template.format(cmd=long_cmd)
                        conf += f'{dkey} = "{dval}"\n{wkey} = {wval}\n'
                    else:
                        conf = base_template.format(cmd=long_cmd)
                        conf += f'[{section}]\n{dkey} = "{dval}"\n{wkey} = {wval}\n'
                    cmd_disp, l, out = run(conf)
                    if l != 80:
                        print(f"FOUND SECTION {section} {dkey}={dval} {wkey}={wval} => len {l} cmd {cmd_disp[:30]}")
                        candidates.append((section,dkey,dval,wkey,wval,l))

# Try just width alone
for wkey in keys_width:
    for wval in [10,20]:
        for section in ["config","default",""]:
            if section=="":
                conf = base_template.format(cmd=long_cmd) + f'{wkey} = {wval}\n'
            else:
                conf = base_template.format(cmd=long_cmd) + f'[{section}]\n{wkey} = {wval}\n'
            cmd_disp,l,out = run(conf)
            if l != 80:
                print(f"FOUND WIDTH ONLY SECTION {section} {wkey}={wval} => len {l}")

# Try just display alone
for dkey in keys_display:
    for dval in ["full","short","Full","Short"]:
        for section in ["config","default",""]:
            if section=="":
                conf = base_template.format(cmd=long_cmd) + f'{dkey} = "{dval}"\n'
            else:
                conf = base_template.format(cmd=long_cmd) + f'[{section}]\n{dkey} = "{dval}"\n'
            cmd_disp,l,out = run(conf)
            if l != 80:
                print(f"FOUND DISPLAY ONLY SECTION {section} {dkey}={dval} => len {l} cmd len {len(long_cmd)}")

# Test baseline no config section besides scripts
conf = base_template.format(cmd=long_cmd)
cmd_disp,l,out = run(conf)
print(f"BASELINE no config: len {l} expected 80? cmd displayed: {cmd_disp}")

# Test with [default] empty (init)
conf = base_template.format(cmd=long_cmd) + "\n[default]\n"
cmd_disp,l,out = run(conf)
print(f"BASELINE with [default] empty: len {l}")

