use serde::Serialize;
use std::collections::BTreeMap;

#[derive(Serialize)]
struct Script {
    command: String,
    description: Option<String>,
    tags: Option<Vec<String>>,
}

#[derive(Serialize)]
struct Config {
    scripts: BTreeMap<String, Script>,
    #[serde(skip_serializing_if = "Option::is_none")]
    default: Option<DefaultCfg>,
}

#[derive(Serialize)]
struct DefaultCfg {
    command_width: Option<usize>,
}

fn main() {
    let tests = vec![
        "a'b",
        "a''b",
        "a'''b",
        "echo 'hi'",
        "a'",
        "'a",
        "''",
        "'",
        "a''",
        "a''a",
        "a\"b",
        "a\"b\"c",
        "a\"b'c",
        "a'b\"c",
        "\"",
        "\"\"",
        "'\"",
        "\"'",
        "echo \"hi\"",
        "echo 'hi' and \"bye\"",
        "desc with \"quotes\" and 'single'",
        "a b c",
        "echo hello\n",
        "echo hello",
        "echo a",
    ];
    for t in tests {
        let mut scripts = BTreeMap::new();
        scripts.insert("test".to_string(), Script { command: t.to_string(), description: None, tags: None });
        let cfg = Config { scripts, default: None };
        let s = toml::to_string(&cfg).unwrap();
        println!("IN:{:?} =>\n{}\n---", t, s);
    }
}
RS
cd /tmp/toml_test && cargo run 2>&1 | head -n 200
"}

